package com.bank.session;

import java.io.*;
import java.util.logging.*;

public class CustomerSession implements Serializable {
    private static final long serialVersionUID = 1L;

    private String accountId;            // persisted normally
    private String holderName;           // persisted normally
    private int loginCount;              // persisted normally

    private transient String password;   // SECURITY: never written to the stream
    private transient String displayName; // DERIVABLE: recomputed from holderName
    private transient Logger log;         // RUNTIME-ONLY: re-established after load

    public CustomerSession(String accountId, String holderName, int loginCount, String password) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.loginCount = loginCount;
        this.password = password;
        this.displayName = deriveDisplayName();
        this.log = Logger.getLogger("BankLog");
    }

    private String deriveDisplayName() {
        return holderName + " (" + accountId + ")";
    }

    // Called automatically during deserialization: restore transient non-sensitive fields.
    private void readObject(ObjectInputStream in) throws IOException, ClassNotFoundException {
        in.defaultReadObject();          // reads the non-transient fields
        this.displayName = deriveDisplayName(); // re-derive the cached display name
        this.log = Logger.getLogger("BankLog"); // re-establish the runtime logger
        // NOTE: password is intentionally NOT restored — it stays null (security).
    }

    public String getAccountId() { return accountId; }
    public String getHolderName() { return holderName; }
    public int getLoginCount() { return loginCount; }
    public String getPassword() { return password; }
    public String getDisplayName() { return displayName; }
    public boolean hasLogger() { return log != null; }
}
