package com.bank.session;

import java.io.*;
import java.util.logging.*;

public class TransientDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        CustomerSession rajesh = new CustomerSession(
            "SAV2001", "Rajesh Kumar", 5, "SuperSecret123");

        log.info(() -> "BEFORE serialize: password=" + rajesh.getPassword()
                        + " displayName=" + rajesh.getDisplayName()
                        + " hasLogger=" + rajesh.hasLogger());

        // Serialize to a byte array (simulating a cache write)
        byte[] bytes;
        try (ByteArrayOutputStream baos = new ByteArrayOutputStream();
             ObjectOutputStream oos = new ObjectOutputStream(baos)) {
            oos.writeObject(rajesh);
            bytes = baos.toByteArray();
        }
        log.info(() -> "Serialized " + bytes.length + " bytes (password NOT among them).");

        // Deserialize (simulating a cache read in another process)
        CustomerSession restored;
        try (ByteArrayInputStream bais = new ByteArrayInputStream(bytes);
             ObjectInputStream ois = new ObjectInputStream(bais)) {
            restored = (CustomerSession) ois.readObject();
        }

        log.info(() -> "AFTER deserialize: accountId=" + restored.getAccountId()
                        + " holderName=" + restored.getHolderName()
                        + " loginCount=" + restored.getLoginCount());
        log.warning(() -> "AFTER deserialize: password=" + restored.getPassword()
                           + " (null — transient, never persisted = SECURE)");
        log.info(() -> "AFTER deserialize: displayName=" + restored.getDisplayName()
                        + " (re-derived in readObject)");
        log.info(() -> "AFTER deserialize: hasLogger=" + restored.hasLogger()
                        + " (re-established in readObject)");
    }
}
